/** Approved source-identical API prose, scoped to its target locale. */
export const LOCALE_VERBATIM_API_PROSE: ReadonlyMap<string, readonly string[]> =
  localeVerbatimApiProse;

/** Rebuild `l10n/docs.api.pot` from the current `docs/api` tree and refresh its coverage reports. */
export const refreshApiPot = ({ force = false }: { force?: boolean } = {}): void => {
  const units = globSync("**/*.md", { cwd: enApiDir })
    .sort()
    .flatMap((file) =>
      collectUnits(segmentMarkdown(readFileSync(join(enApiDir, file), "utf8"), { scope: file }))
        // Glossary units are deterministically substituted and never written to the PO catalog
        // (see segment-markdown.ts) — including them here would make 100% coverage unreachable.
        .filter(isCatalogedApiUnit)
        .map((unit) => ({
          msgid: unit.text,
          msgctxt: `docs.api:${unit.kind}`,
          reference: relative(enApiDir, join(enApiDir, file)),
          flags: VERBATIM_API_PROSE.has(unit.text) ? [PANTOKEN_VERBATIM_FLAG] : [],
          translate: "always" as const,
        })),
    );
  const catalogPath = join(repoRoot, "l10n", "docs.api.pot");
  const catalog = serializePot(units, ["no-c-format"]);
  if (force) writeFileSync(catalogPath, catalog);
  else writeCatalog(catalogPath, catalog);
  refreshCoverageReports(join(repoRoot, "i18n.config.json"));
};

/** Repair missing or suspect docs.api PO entries with the configured translation provider. */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { AiTranslationAdapter } from "./api-translation.ts";
import { isPassthroughTranslation } from "@pantoken/translation-adapters";
import {
  LOCALE_VERBATIM_API_PROSE,
  PANTOKEN_VERBATIM_FLAG,
  refreshApiPot,
} from "./refresh-api-pot.ts";
import {
  mergePoWithTemplate,
  parsePo,
  refreshCoverageReports,
  serializePo,
  writeCatalog,
} from "@pantoken/i18n-engine";

const repoRoot = new URL("../../", import.meta.url).pathname;
const locale = process.env.DOCS_TRANSLATION_LOCALE ?? "hu";
const potPath = join(repoRoot, "l10n", "docs.api.pot");
// The drift-fix flow diffs docs/api against the on-disk POT without regenerating it first, so a POT
// that predates new/changed API content would never gain entries for those units — merge would have
// nothing to fill, leaving the drift permanently unfixable. Rebuild it here so it always matches
// the current EN API tree.
refreshApiPot();
const path = join(repoRoot, "l10n", locale, "docs.api.po");
await mergePoWithTemplate(path, potPath);
const entries = parsePo(readFileSync(path, "utf8"));
const localeVerbatimSources = new Set(LOCALE_VERBATIM_API_PROSE.get(locale) ?? []);
let markedVerbatim = false;
for (const entry of entries) {
  const requiredVerbatim =
    entry.flags.includes(PANTOKEN_VERBATIM_FLAG) || localeVerbatimSources.has(entry.msgid);
  if (
    !entry.obsolete &&
    requiredVerbatim &&
    (entry.msgstr === "" || entry.msgstr.trim().toLowerCase() === entry.msgid.trim().toLowerCase())
  ) {
    entry.msgstr = entry.msgid;
    entry.fuzzy = false;
    entry.flags = entry.flags.filter((flag) => flag !== "fuzzy");
    if (!entry.flags.includes(PANTOKEN_VERBATIM_FLAG))
      entry.flags = [...entry.flags, PANTOKEN_VERBATIM_FLAG];
    markedVerbatim = true;
  }
}
if (markedVerbatim) {
  writeCatalog(path, serializePo(entries));
  refreshCoverageReports(join(repoRoot, "i18n.config.json"));
}

const requestedUnits = process.env.DOCS_TRANSLATION_UNITS
  ? (JSON.parse(process.env.DOCS_TRANSLATION_UNITS) as Array<{ msgctxt?: string; msgid: string }>)
  : undefined;
const selected = requestedUnits
  ? new Set(requestedUnits.map((unit) => `${unit.msgctxt ?? ""}\u0000${unit.msgid}`))
  : undefined;
const allowsVerbatim = (entry: (typeof entries)[number]): boolean =>
  /^en(?:-|$)/u.test(locale) ||
  entry.flags.includes(PANTOKEN_VERBATIM_FLAG) ||
  localeVerbatimSources.has(entry.msgid);
const needsTranslation = (entry: (typeof entries)[number]): boolean =>
  !entry.obsolete &&
  (entry.msgstr === "" ||
    entry.fuzzy ||
    (!allowsVerbatim(entry) && isPassthroughTranslation(entry.msgid, entry.msgstr)));
const missing = entries.filter(
  (entry) =>
    needsTranslation(entry) &&
    (selected === undefined || selected.has(`${entry.msgctxt ?? ""}\u0000${entry.msgid}`)),
);
const translatedIds = new Set<string>();

if (missing.length > 0) {
  const adapter = new AiTranslationAdapter(locale);
  const byId = new Map(missing.map((entry) => [`${entry.msgctxt ?? ""}\0${entry.msgid}`, entry]));
  const persistChunk = (translations: Record<string, string>): void => {
    for (const [id, translation] of Object.entries(translations)) {
      const entry = byId.get(id);
      if (
        entry !== undefined &&
        translation.trim() !== "" &&
        (allowsVerbatim(entry) || !isPassthroughTranslation(entry.msgid, translation))
      ) {
        entry.msgstr = translation;
        entry.fuzzy = false;
        entry.flags = entry.flags.filter((flag) => flag !== "fuzzy");
        translatedIds.add(id);
      }
    }
    writeCatalog(path, serializePo(entries));
    refreshCoverageReports(join(repoRoot, "i18n.config.json"));
  };
  await adapter.translateBatch(
    missing.map((entry) => ({
      id: `${entry.msgctxt ?? ""}\0${entry.msgid}`,
      text: entry.msgid,
    })),
    persistChunk,
  );
}

console.log(
  `${locale}: filled ${translatedIds.size}; remaining ${entries.filter(needsTranslation).length}`,
);

set(kind: string, source: string, translation: string, options?: { verbatim?: boolean }): void {
  assertGeneratedTranslation(source, translation);
  const verbatim = options?.verbatim === true;
  if (this._poByKey) {
    this.setPoTranslation(kind, source, translation, verbatim);
  } else {
    this._mem!.set(keyFor(kind, source), translation);
    if (verbatim) this._mem!.set(verbatimKey(kind, source), "1");
  }
  this.misses++;
}

private setPoTranslation(
  kind: string,
  source: string,
  translation: string,
  verbatim: boolean,
): void {
  const key = `docs.api:${kind}\0${source}`;
  let entry = this._poByKey!.get(key);
  if (!entry) {
    entry = {
      msgid: source,
      msgstr: "",
      msgctxt: `docs.api:${kind}`,
      references: [],
      flags: [],
      fuzzy: false,
      obsolete: false,
    };
    this._poEntries!.push(entry);
    this._poByKey!.set(key, entry);
  }
  entry.msgstr = alignTrailingNewline(source, translation);
  entry.fuzzy = false;
  const flags = new Set(entry.flags);
  flags.delete("fuzzy");
  if (verbatim) flags.add(VERBATIM_FLAG);
  entry.flags = [...flags];
}

/** True when the stored translation for `source` was deliberately accepted as identical to English. */
isVerbatim(kind: string, source: string): boolean {
  if (this._poByKey) {
    return (
      this._poByKey.get(`docs.api:${kind}\0${source}`)?.flags.includes(VERBATIM_FLAG) === true
    );
  }
  const key = verbatimKey(kind, source);
  if (!this._mem!.has(key)) return false;
  // Re-set rather than get: marks the marker used (so pruning keeps it) without counting a hit.
  this._mem!.set(key, "1");
  return true;
}

save(): void {
  if (this._poEntries && this._poPath) {
    mkdirSync(dirname(this._poPath), { recursive: true });
    writeCatalog(this._poPath, serializePo(this._poEntries));
    refreshCoverageReports(join(import.meta.dirname, "..", "..", "i18n.config.json"));
  } else this._mem!.save();

