  for (const text of LOCALE_VERBATIM_API_PROSE.get(locale) ?? []) {
    const e = bySource.get(text);
    if (e && (e.msgstr === '' || e.msgstr.trim().toLowerCase() === e.msgid.trim().toLowerCase())) {
      if (!e.flags.includes(PANTOKEN_VERBATIM_FLAG) || e.fuzzy || e.msgstr !== e.msgid) throw new Error(`${path}: bad locale marker ${JSON.stringify(text)}`);
      localeChecked++;
    }
  }
}
console.log(`Validated ${globalChecked} global and ${localeChecked} locale-specific active PO entries across ${paths.length} catalogs.`);
